<?php
$totaisRomaneio = [];
$statusFila = [];
$inconformesFila = [];
foreach (($fila ?? []) as $pedidoFila) {
    $statusFila[(int)$pedidoFila['id']] = strtolower((string)($pedidoFila['status'] ?? ''));
    $inconformesFila[(int)$pedidoFila['id']] = count(array_filter($pedidoFila['itens'] ?? [], static fn(array $item): bool => ($item['picking_status'] ?? '') === 'x'));
}
foreach (($disponiveisRomaneio ?? []) as $pedidoRomaneio) {
    $quantidade = 0.0;
    $peso = 0.0;
    foreach (($pedidoRomaneio['itens'] ?? []) as $itemRomaneio) {
        $quantidadeItem = (float)($itemRomaneio['quantidade'] ?? 0);
        $quantidade += $quantidadeItem;
        $peso += $quantidadeItem * (float)($itemRomaneio['peso_liquido'] ?? 0);
    }
    $totaisRomaneio[(int)$pedidoRomaneio['id']] = ['volumes' => max(1, (int)ceil($quantidade)), 'peso' => round($peso, 3)];
}
?>
<script>
(() => {
    const totaisRomaneio=<?= json_encode($totaisRomaneio, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
    const statusFila=<?= json_encode($statusFila, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
    const inconformesFila=<?= json_encode($inconformesFila, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); ?>;
    document.querySelectorAll('.expedicao-status.separacao').forEach(status=>status.textContent='Separado');
    document.querySelectorAll('[data-tab-panel="fila"] tbody tr').forEach(row=>{const id=Number(row.cells?.[0]?.textContent?.trim()),status=row.querySelector('.expedicao-status');if(!status)return;if(statusFila[id]==='separando'){status.textContent='Separando';status.classList.remove('aprovado');status.classList.add('separando')}else if(statusFila[id]==='producao'){status.textContent='Aprovado';status.classList.remove('separando');status.classList.add('aprovado')}});
    document.querySelectorAll('[data-tab-panel="fila"] tbody tr').forEach(row=>{const id=Number(row.cells?.[0]?.textContent?.trim()),status=row.querySelector('.expedicao-status');if(status&&inconformesFila[id]>0){status.classList.add('inconforme');status.textContent=`⚠ Inconforme (${inconformesFila[id]})`;status.style.cssText='color:#b91c1c;background:#fee2e2;border:1px solid #fecaca'}});
    document.querySelectorAll('[data-tab-panel="fila"] .expedicao-store').forEach(store=>{const strong=store.querySelector('strong'),name=strong?.textContent?.trim()||'',length=name.length;store.title=name;store.classList.toggle('is-long',length>28&&length<=50);store.classList.toggle('is-very-long',length>50);requestAnimationFrame(()=>{const lineHeight=Number.parseFloat(getComputedStyle(strong).lineHeight)||16;store.classList.toggle('has-long-name',strong.scrollHeight>lineHeight+2)})});
    const queueBody=document.querySelector('[data-tab-panel="fila"] tbody'),queueRows=queueBody?[...queueBody.querySelectorAll('tr')].filter(row=>!row.querySelector('.expedicao-empty')):[],queueStatusControl=document.querySelector('.expedicao-queue-status-control'),queueStatusTrigger=document.querySelector('[data-queue-status-trigger]'),queueStatusMenu=document.querySelector('[data-queue-status-menu]'),queueStatusLabel=document.querySelector('[data-queue-status-label]'),queueStatusOptions=[...document.querySelectorAll('[data-queue-status-option]')];let queueStatusValue='';const applyQueueStatus=()=>queueRows.forEach(row=>row.hidden=Boolean(queueStatusValue)&&!row.cells[3]?.textContent?.trim().toLocaleLowerCase('pt-BR').includes(queueStatusValue));const closeQueueStatus=()=>{queueStatusMenu?.setAttribute('hidden','');queueStatusTrigger?.setAttribute('aria-expanded','false')};queueStatusTrigger?.addEventListener('click',()=>{const open=queueStatusMenu?.hasAttribute('hidden');if(open){queueStatusMenu.removeAttribute('hidden');queueStatusTrigger.setAttribute('aria-expanded','true')}else closeQueueStatus()});queueStatusOptions.forEach(option=>option.addEventListener('click',()=>{queueStatusValue=option.dataset.queueStatusOption||'';if(queueStatusLabel)queueStatusLabel.textContent=option.textContent.trim();queueStatusControl.className='expedicao-queue-status-control'+(queueStatusValue?` is-${queueStatusValue}`:'');queueStatusOptions.forEach(item=>item.classList.toggle('is-selected',item===option));applyQueueStatus();closeQueueStatus()}));queueStatusOptions[0]?.classList.add('is-selected');document.addEventListener('click',event=>{if(!queueStatusControl?.contains(event.target))closeQueueStatus()});
    const queueSortButtons=[...document.querySelectorAll('[data-queue-sort]')],queueOriginalRows=[...queueRows];let queueSort={column:-1,direction:''};queueSortButtons.forEach(button=>button.addEventListener('click',()=>{if(!queueBody)return;const column=Number(button.dataset.queueSort),type=button.dataset.sortType||'text';if(queueSort.column!==column||!queueSort.direction)queueSort={column,direction:'asc'};else if(queueSort.direction==='asc')queueSort.direction='desc';else queueSort={column:-1,direction:''};const rows=[...queueOriginalRows];if(queueSort.direction){const direction=queueSort.direction==='asc'?1:-1;rows.sort((a,b)=>{const left=a.cells[column]?.textContent?.trim()||'',right=b.cells[column]?.textContent?.trim()||'';return direction*left.localeCompare(right,'pt-BR',{numeric:true,sensitivity:'base'})})}rows.forEach(row=>queueBody.appendChild(row));queueSortButtons.forEach(item=>{const active=item===button&&Boolean(queueSort.direction),indicator=item.querySelector('span');if(indicator){indicator.textContent=active?(queueSort.direction==='asc'?'▲':'▼'):'⇅';indicator.classList.toggle('active',active)}});applyQueueStatus()}));
    const queueStatusIcon=document.querySelector('[data-queue-status-icon]'),queueIconMarkup={aprovado:'<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="m8 12 2.5 2.5L16 9"/></svg>',separando:'<svg viewBox="0 0 24 24"><path d="m12 2 9 5-9 5-9-5z"/><path d="m3 7 9 5 9-5v10l-9 5-9-5z"/></svg>',separado:'<svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="16" rx="2"/><path d="m8 12 2.5 2.5L16 9"/></svg>',inconforme:'<svg viewBox="0 0 24 24"><path d="M12 3 2 21h20z"/><path d="M12 9v5M12 18h.01"/></svg>'};queueStatusOptions.forEach(option=>option.addEventListener('click',()=>{if(queueStatusIcon)queueStatusIcon.innerHTML=queueIconMarkup[option.dataset.queueStatusOption]||'<svg viewBox="0 0 24 24"><path d="M4 5h16l-6 7v5l-4 2v-7z"/></svg>'}));
    const tabs=[...document.querySelectorAll('.expedicao-tab')],panels=[...document.querySelectorAll('.expedicao-panel')];
    const activate=(target)=>{tabs.forEach(tab=>{const active=tab.dataset.tabTarget===target;tab.classList.toggle('is-active',active);tab.setAttribute('aria-selected',active?'true':'false')});panels.forEach(panel=>panel.hidden=panel.dataset.tabPanel!==target)};
    tabs.forEach(tab=>tab.addEventListener('click',()=>activate(tab.dataset.tabTarget)));
    const requested=new URLSearchParams(window.location.search).get('tab');if(['fila','romaneio','concluidos'].includes(requested))activate(requested);
    const pedidoSelect=document.querySelector('.romaneio-form select[name="pedido_id"]'),volumeInput=document.querySelector('.romaneio-form input[name="volumes"]'),pesoInput=document.querySelector('.romaneio-form input[name="peso_total"]');
    const preencherTotais=()=>{const dados=totaisRomaneio[pedidoSelect?.value];if(!dados)return;if(volumeInput)volumeInput.value=dados.volumes;if(pesoInput)pesoInput.value=Number(dados.peso).toFixed(3)};pedidoSelect?.addEventListener('change',preencherTotais);
    document.querySelectorAll('[data-select-expedition]').forEach(button=>button.addEventListener('click',()=>{activate('romaneio');if(pedidoSelect){pedidoSelect.value=button.dataset.selectExpedition;preencherTotais();pedidoSelect.focus()}document.querySelector('.romaneio-form-card')?.scrollIntoView({behavior:'smooth',block:'center'})}));
    const completedSearch=document.querySelector('[data-expedicao-completed-search]'),completedBody=document.querySelector('[data-tab-panel="concluidos"] tbody');
    if(completedSearch&&completedBody){const statusFilter=document.querySelector('[data-expedicao-status-filter]'),rows=[...completedBody.querySelectorAll('tr')].filter(row=>!row.querySelector('.expedicao-empty'));const empty=document.createElement('tr');empty.className='expedicao-completed-no-results';empty.hidden=true;empty.innerHTML='<td colspan="8">Nenhum pedido encontrado para esta busca.</td>';completedBody.appendChild(empty);const normalize=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');const filter=()=>{const term=normalize(completedSearch.value),status=normalize(statusFilter?.value||''),visible=rows.reduce((count,row)=>{const rowText=normalize(row.textContent),rowStatus=normalize(row.cells[7]?.textContent||''),match=(!term||rowText.includes(term))&&(!status||rowStatus.includes(status));row.hidden=!match;return count+(match?1:0)},0);empty.hidden=visible>0||rows.length===0;statusFilter?.classList.toggle('is-active',Boolean(status))};completedSearch.addEventListener('input',filter);statusFilter?.addEventListener('change',filter);filter()}
    const completedStatusSelect=document.querySelector('[data-expedicao-status-filter]'),completedStatusControl=completedStatusSelect?.closest('.expedicao-completed-status-control'),completedStatusIcon=completedStatusControl?.querySelector('[data-expedicao-status-icon]');const renderCompletedStatusFilter=()=>{const value=completedStatusSelect?.value||'';completedStatusControl?.classList.toggle('is-expedido',value==='expedido');completedStatusControl?.classList.toggle('is-faturado',value==='faturado');if(completedStatusIcon)completedStatusIcon.innerHTML=value==='expedido'?'<svg viewBox="0 0 24 24"><path d="M3 6h11v11H3zM14 10h4l3 3v4h-7z"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/></svg>':value==='faturado'?'<svg viewBox="0 0 24 24"><path d="M12 3l2.2 1.4 2.6-.2 1.2 2.3 2.2 1.4-.5 2.6 1.2 2.3-1.8 1.9-.5 2.6-2.6.6-1.8 1.9-2.2-1.4-2.2 1.4-1.8-1.9-2.6-.6-.5-2.6-1.8-1.9 1.2-2.3-.5-2.6 2.2-1.4 1.2-2.3 2.6.2z"/><path d="m8.5 12 2.2 2.2 4.8-4.8"/></svg>':'<svg viewBox="0 0 24 24"><path d="M4 5h16l-6 7v5l-4 2v-7z"/></svg>'};completedStatusSelect?.addEventListener('change',renderCompletedStatusFilter);renderCompletedStatusFilter();
    const statusTrigger=document.querySelector('[data-status-filter-trigger]'),statusMenu=document.querySelector('[data-status-filter-menu]'),statusLabel=document.querySelector('[data-status-filter-label]'),statusOptions=[...document.querySelectorAll('[data-status-option]')];const closeStatusMenu=()=>{statusMenu?.setAttribute('hidden','');statusTrigger?.setAttribute('aria-expanded','false')};statusTrigger?.addEventListener('click',()=>{const opening=statusMenu?.hasAttribute('hidden');if(opening){statusMenu?.removeAttribute('hidden');statusTrigger.setAttribute('aria-expanded','true')}else closeStatusMenu()});statusOptions.forEach(option=>option.addEventListener('click',()=>{if(completedStatusSelect){completedStatusSelect.value=option.dataset.statusOption||'';completedStatusSelect.dispatchEvent(new Event('change',{bubbles:true}))}if(statusLabel)statusLabel.textContent=option.textContent.trim();statusOptions.forEach(item=>item.classList.toggle('is-selected',item===option));closeStatusMenu()}));document.addEventListener('click',event=>{if(!completedStatusControl?.contains(event.target))closeStatusMenu()});statusOptions[0]?.classList.add('is-selected');
    document.querySelectorAll('[data-tab-panel="concluidos"] .expedicao-cell-clamp').forEach(cell=>{const length=cell.textContent.trim().length;cell.classList.toggle('is-long',length>34&&length<=55);cell.classList.toggle('is-very-long',length>55)});
    const completedSortButtons=[...document.querySelectorAll('[data-expedicao-sort]')],completedOriginalRows=completedBody?[...completedBody.querySelectorAll('tr')].filter(row=>!row.querySelector('.expedicao-empty')):[];let completedSort={column:-1,direction:''};completedSortButtons.forEach(button=>button.addEventListener('click',()=>{if(!completedBody)return;const column=Number(button.dataset.expedicaoSort),type=button.dataset.sortType||'text';if(completedSort.column!==column||!completedSort.direction){completedSort={column,direction:'asc'}}else if(completedSort.direction==='asc'){completedSort.direction='desc'}else{completedSort={column:-1,direction:''}}const rows=[...completedOriginalRows];if(completedSort.direction){const direction=completedSort.direction==='asc'?1:-1;rows.sort((a,b)=>{const left=a.cells[column]?.textContent?.trim()||'',right=b.cells[column]?.textContent?.trim()||'';if(type==='date')return direction*((Date.parse(left.replace(' ','T'))||0)-(Date.parse(right.replace(' ','T'))||0));return direction*left.localeCompare(right,'pt-BR',{numeric:true,sensitivity:'base'})})}rows.forEach(row=>completedBody.insertBefore(row,completedBody.querySelector('.expedicao-completed-no-results')));completedSortButtons.forEach(item=>{const active=item===button&&Boolean(completedSort.direction),indicator=item.querySelector('span');item.setAttribute('aria-sort',active?(completedSort.direction==='asc'?'ascending':'descending'):'none');if(indicator){indicator.textContent=active?(completedSort.direction==='asc'?'▲':'▼'):'⇅';indicator.classList.toggle('active',active)}})}));
